// 2. Validate Inbound Lead Data
const body = $input.first().json.body || $input.first().json;

const requiredFields = ['fullName', 'companyName', 'email', 'industry', 'employees', 'monthlyLeadVolume', 'biggestProblem', 'currentTools'];
const missing = [];

for (const field of requiredFields) {
  if (!body[field] || typeof body[field] !== 'string' || body[field].trim().length === 0) {
    missing.push(field);
  }
}

if (body.email && !body.email.includes('@')) {
  missing.push('valid email');
}

if (missing.length > 0) {
  return [{
    json: {
      isValid: false,
      error: `Validation error: Missing or invalid fields: ${missing.join(', ')}`,
      originalLead: body,
      leadId: body.leadId || `lead_${Date.now()}`
    }
  }];
}

return [{
  json: {
    isValid: true,
    lead: body,
    leadId: body.leadId || `lead_${Date.now()}`
  }
}];

// 4. Parse JSON & Exception Guard
const rawAiResponse = $input.first().json.message?.content || $input.first().json.text || $input.first().json.response || '';
const lead = $('2. Validate Inbound Lead').first().json.lead;
const leadId = $('2. Validate Inbound Lead').first().json.leadId;

function sanitizeAiResponse(raw) {
  if (typeof raw !== 'string') return raw;
  return raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
}

let parsed = null;
try {
  const cleanText = sanitizeAiResponse(rawAiResponse);
  parsed = JSON.parse(cleanText);
} catch (err) {
  return [{
    json: {
      status: 'EXCEPTION',
      routing: 'EXCEPTION',
      leadId,
      originalLead: lead,
      errorReason: 'Malformed AI JSON output: ' + err.message,
      rawAiResponse,
      manualReviewRequired: true,
      timestamp: new Date().toISOString()
    }
  }];
}

const validClassifications = ['HOT', 'WARM', 'COLD'];
const isScoreValid = typeof parsed.lead_score === 'number' && parsed.lead_score >= 0 && parsed.lead_score <= 100;
const isClassValid = validClassifications.includes(parsed.classification);

if (!isScoreValid || !isClassValid || !parsed.primary_problem || !parsed.automation_opportunity) {
  return [{
    json: {
      status: 'EXCEPTION',
      routing: 'EXCEPTION',
      leadId,
      originalLead: lead,
      errorReason: 'AI response failed schema validation constraints',
      rawAiResponse: parsed,
      manualReviewRequired: true,
      timestamp: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    status: 'QUALIFIED',
    routing: parsed.classification,
    leadId,
    originalLead: lead,
    qualification: parsed,
    timestamp: new Date().toISOString()
  }
}];

// HOT Lead: Prepare Email 1 (Confirmation) & Email 2 (Internal Notification)
const parsed = $('4. Parse JSON & Exception Guard').item.json;
const lead = parsed.originalLead;
const q = parsed.qualification;
const hubspot = $input.first().json;
const leadId = parsed.leadId;

const salesEmail = $env.FLOWFOUNDRY_SALES_EMAIL || 'sales@flowfoundry.io';
const fromEmail = $env.RESEND_FROM_EMAIL || 'FlowFoundry <onboarding@resend.dev>';
const firstName = lead.fullName.split(' ')[0] || 'there';

// EMAIL 1: Lead confirmation (professional & concise)
const confirmationPayload = {
  from: fromEmail,
  to: [lead.email],
  subject: 'Automation Audit Request Received — FlowFoundry',
  text: `Hello ${firstName},\n\nThank you for requesting an Automation Audit for ${lead.companyName}. We have successfully received your intake details regarding: ${q.primary_problem}.\n\nBased on your volume (${lead.monthlyLeadVolume}) and stack (${lead.currentTools}), your workflows show strong alignment with our automation engine. We recommend a 25-minute technical discovery session to review architectural requirements:\n\nhttps://flowfoundry.io/schedule?lead=${leadId}\n\nBest regards,\nThe FlowFoundry Solutions Architecture Team\nhttps://flowfoundry.io`
};

// EMAIL 2: Internal sales notification for HOT lead
const internalNotificationPayload = {
  from: fromEmail,
  to: [salesEmail],
  subject: `🔥 NEW HOT LEAD: ${lead.companyName} (Score: ${q.lead_score}/100)`,
  text: `================================================\nNEW HOT LEAD\n================================================\n\nCompany: ${lead.companyName}\nContact: ${lead.fullName} (${lead.email}${lead.phone ? ' / ' + lead.phone : ''})\nLead Score: ${q.lead_score}/100\nClassification: ${q.classification}\nPrimary Problem: ${q.primary_problem}\nAutomation Opportunity: ${q.automation_opportunity}\nRecommended Next Step: ${q.recommended_next_step}\n\nLead ID: ${leadId}\nEmployees: ${lead.employees}\nMonthly Lead Volume: ${lead.monthlyLeadVolume}\nCurrent Tools: ${lead.currentTools}\nWebsite: ${lead.website || 'N/A'}\nEvaluation Reasoning: ${q.reasoning}`
};

return [{
  json: {
    status: 'HOT_PREPARED',
    leadId,
    classification: 'HOT',
    lead,
    qualification: q,
    hubspotContactId: hubspot.id || hubspot.vid || 'upserted',
    confirmationPayload,
    internalNotificationPayload
  }
}];

// WARM Lead: Prepare Email 1 (Confirmation) & Email 2 (Internal Notification)
const parsed = $('4. Parse JSON & Exception Guard').item.json;
const lead = parsed.originalLead;
const q = parsed.qualification;
const hubspot = $input.first().json;
const leadId = parsed.leadId;

const salesEmail = $env.FLOWFOUNDRY_SALES_EMAIL || 'sales@flowfoundry.io';
const fromEmail = $env.RESEND_FROM_EMAIL || 'FlowFoundry <onboarding@resend.dev>';
const firstName = lead.fullName.split(' ')[0] || 'there';

// EMAIL 1: Lead confirmation (professional & concise)
const confirmationPayload = {
  from: fromEmail,
  to: [lead.email],
  subject: 'Automation Audit Request Received — FlowFoundry',
  text: `Hello ${firstName},\n\nThank you for sharing your operational requirements for ${lead.companyName}. We have successfully received your details regarding: ${q.primary_problem}.\n\nOur engineering team evaluates submissions in detail to ensure targeted architecture recommendations. A solutions consultant will review your stack and follow up with you within 24 to 48 business hours.\n\nWarm regards,\nThe FlowFoundry Team\nhttps://flowfoundry.io`
};

// EMAIL 2: Internal notification for WARM lead
const internalNotificationPayload = {
  from: fromEmail,
  to: [salesEmail],
  subject: `⚡ NEW WARM LEAD: ${lead.companyName} (Score: ${q.lead_score}/100)`,
  text: `================================================\nNEW WARM LEAD\n================================================\n\nCompany: ${lead.companyName}\nContact: ${lead.fullName} (${lead.email}${lead.phone ? ' / ' + lead.phone : ''})\nLead Score: ${q.lead_score}/100\nClassification: ${q.classification}\nPrimary Problem: ${q.primary_problem}\nAutomation Opportunity: ${q.automation_opportunity}\nRecommended Action: Review within 24-48 business hours & initiate follow-up outreach\n\nLead ID: ${leadId}\nEmployees: ${lead.employees}\nMonthly Lead Volume: ${lead.monthlyLeadVolume}\nCurrent Tools: ${lead.currentTools}`
};

return [{
  json: {
    status: 'WARM_PREPARED',
    leadId,
    classification: 'WARM',
    lead,
    qualification: q,
    hubspotContactId: hubspot.id || hubspot.vid || 'upserted',
    confirmationPayload,
    internalNotificationPayload
  }
}];

// COLD Lead: Prepare Email 1 (Confirmation) & Email 2 (Internal Notification)
const parsed = $('4. Parse JSON & Exception Guard').item.json;
const lead = parsed.originalLead;
const q = parsed.qualification;
const hubspot = $input.first().json;
const leadId = parsed.leadId;

const salesEmail = $env.FLOWFOUNDRY_SALES_EMAIL || 'sales@flowfoundry.io';
const fromEmail = $env.RESEND_FROM_EMAIL || 'FlowFoundry <onboarding@resend.dev>';
const firstName = lead.fullName.split(' ')[0] || 'there';

// EMAIL 1: Lead confirmation (resources & blueprints)
const confirmationPayload = {
  from: fromEmail,
  to: [lead.email],
  subject: 'Automation Audit Request Received — FlowFoundry',
  text: `Hello ${firstName},\n\nThank you for your interest in FlowFoundry. We have received your inquiry for ${lead.companyName}.\n\nWhile our custom enterprise engagements focus on high-velocity inbound pipelines, we publish comprehensive architectural blueprints and automation guides that may assist your team:\nhttps://flowfoundry.io/resources\n\nSincerely,\nFlowFoundry Resources\nhttps://flowfoundry.io`
};

// EMAIL 2: Internal notification for COLD lead (nurture rule)
const internalNotificationPayload = {
  from: fromEmail,
  to: [salesEmail],
  subject: `📋 NEW INBOUND LEAD (COLD / NURTURE): ${lead.companyName} (Score: ${q.lead_score}/100)`,
  text: `================================================\nNEW COLD LEAD (NURTURE)\n================================================\n\nCompany: ${lead.companyName}\nContact: ${lead.fullName} (${lead.email})\nLead Score: ${q.lead_score}/100\nClassification: ${q.classification}\nPrimary Problem: ${q.primary_problem}\nAutomation Opportunity: ${q.automation_opportunity}\nWorkflow Action: Enrolled in educational nurture campaign / low-touch sequence\n\nLead ID: ${leadId}`
};

return [{
  json: {
    status: 'COLD_PREPARED',
    leadId,
    classification: 'COLD',
    lead,
    qualification: q,
    hubspotContactId: hubspot.id || hubspot.vid || 'upserted',
    confirmationPayload,
    internalNotificationPayload
  }
}];

// Log Email Delivery Success & Compile Final Status
const confirmationRes = $('7. Resend: Send Lead Confirmation (Email 1)').first()?.json || {};
const internalRes = $input.first().json || {};
const context = $('HOT: Prepare Resend Payloads').first()?.json || $('WARM: Prepare Resend Payloads').first()?.json || $('COLD: Prepare Resend Payloads').first()?.json || {};

console.log(`[FlowFoundry n8n] Resend emails dispatched for lead ${context.leadId} (${context.classification}). Confirmation: ${confirmationRes.id || 'sent'}, Internal: ${internalRes.id || 'sent'}`);

return [{
  json: {
    status: `${context.classification}_PROCESSED`,
    emailIntegrationStatus: 'SENT',
    leadId: context.leadId,
    classification: context.classification,
    confirmationMessageId: confirmationRes.id || 'sent',
    internalMessageId: internalRes.id || 'sent',
    hubspotContactId: context.hubspotContactId,
    timestamp: new Date().toISOString()
  }
}];

// Email Failure Exception Handler
// Preserves lead data, logs integration error safely without exposing API keys, and avoids workflow crash
const errorData = $input.first().json;
const context = $('HOT: Prepare Resend Payloads').first()?.json || $('WARM: Prepare Resend Payloads').first()?.json || $('COLD: Prepare Resend Payloads').first()?.json || {};
const lead = context.lead;
const leadId = context.leadId || `lead_${Date.now()}`;

const rawMessage = errorData.error?.message || errorData.message || JSON.stringify(errorData);
const safeError = rawMessage.replace(/re_[a-zA-Z0-9_]+/g, '[REDACTED_RESEND_KEY]');

console.error(`[FlowFoundry n8n] Resend email delivery failed for lead ${leadId}: ${safeError}`);

return [{
  json: {
    status: 'PROCESSED_WITH_EMAIL_WARNING',
    emailIntegrationStatus: 'FAILED',
    leadId,
    originalLead: lead,
    errorReason: safeError,
    leadPreserved: true,
    manualReviewRequired: false,
    timestamp: new Date().toISOString()
  }
}];

// HubSpot Failure Exception Handler
// Preserves lead in DB, logs error safely, routes to quarantine, avoids data loss
const errorData = $input.first().json;
const parsed = $('4. Parse JSON & Exception Guard').item.json;
const lead = parsed.originalLead;
const leadId = parsed.leadId;

const safeError = errorData.error?.message || errorData.message || 'HubSpot API operation failed';

console.error(`[FlowFoundry n8n] HubSpot sync error for lead ${leadId}: ${safeError}`);

return [{
  json: {
    status: 'EXCEPTION_HUBSPOT_FAILED',
    leadId,
    originalLead: lead, // Complete original lead data preserved
    qualification: parsed.qualification,
    errorReason: safeError,
    manualReviewRequired: true,
    quarantineStage: 'hubspot_sync_failure',
    opsAlert: {
      channel: '#ops-crm-failures',
      text: `⚠️ *HubSpot CRM Sync Failed*\n*Lead ID:* ${leadId}\n*Company:* ${lead.companyName}\n*Email:* ${lead.email}\n*Error:* ${safeError}\n*Status:* Lead safely preserved in database. Routed to exception queue.`
    },
    timestamp: new Date().toISOString()
  }
}];

// General AI Parsing Exception Handler
const item = $input.first().json;
console.warn('[FlowFoundry n8n] AI parsing exception for lead:', item.leadId);

return [{
  json: {
    status: 'EXCEPTION_AI_FAILED',
    leadId: item.leadId,
    originalLead: item.originalLead,
    errorReason: item.errorReason,
    manualReviewRequired: true,
    quarantineStage: 'ai_qualification_failure',
    opsAlert: {
      channel: '#ops-lead-exceptions',
      text: `⚠️ *Lead Qualification Exception*\n*Lead ID:* ${item.leadId}\n*Reason:* ${item.errorReason}\n*Action:* Original data preserved in database. Routed to manual review.`
    },
    timestamp: item.timestamp
  }
}];
